258. impl<const N: usize, const A: usize, S: BssStorage> FixedSizeBumpAllocator<N, A, S> {
259.     ///
260.     /// # Description
261.     ///
262.     /// Creates a new fixed-size bump allocator.
263.     ///
264.     /// # Returns
265.     ///
266.     /// Returns a new allocator.
267.     ///
268.     /// # Safety
269.     ///
270.     /// The caller must ensure that only **one** `FixedSizeBumpAllocator` instance exists for a
271.     /// given `S: BssStorage` backend at any time. Creating multiple allocators over the same
272.     /// backend causes independent bump counters, which leads to overlapping slot reservations
273.     /// and undefined behavior (multiple `&'static mut` references to the same memory).
274.     ///
275.     pub const unsafe fn new() -> Self {
276.         Self {
277.             next_slot: AtomicUsize::new(0),
278.             _storage: PhantomData,
279.         }
280.     }
281. 
282.     ///
283.     /// # Description
284.     ///
285.     /// Allocates the next fixed-size slot as a raw byte array.
286.     ///
287.     /// # Returns
288.     ///
289.     /// On success, returns a mutable reference to a unit-sized byte array.
290.     ///
291.     /// # Errors
292.     ///
293.     /// - [`BumpAllocError::Exhausted`] if storage capacity is exhausted.
294.     /// - [`BumpAllocError::Overflow`] if internal arithmetic overflows.
295.     /// - [`BumpAllocError::OutOfBounds`] if computed slot exceeds storage bounds.
296.     /// - [`BumpAllocError::Misaligned`] if computed slot is not properly aligned.
297.     ///
298.     // SAFETY-SPEC: `external_body` because the success path materializes a
299.     // `&'static mut [u8; N]` from a backend-provided address (`usize as *mut`), a
300.     // raw-memory operation Verus cannot verify without a `PointsTo` permission for
301.     // the externally-owned `BssStorage` region. Mirrors the `src/libs/raw-array`
302.     // pattern. Registered in `verus-ai-logs/tcb-allowed.md`.
303.     #[verus_verify(external_body)]
304.     #[verus_spec(result =>
305.         requires bump_view(self).inv(),
306.         ensures
307.             match result {
308.                 Ok(slot) => {
309.                     let v = bump_view(self);
310.                     let a = slot_ref_addr(slot);
311.                     &&& a % (v.unit_align as int) == 0
312.                     &&& v.base <= a
313.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
314.                 },
315.                 Err(e) => e == BumpAllocError::Exhausted,
316.             },
317.     )]
318.     pub fn alloc(&self) -> Result<&'static mut [u8; N], BumpAllocError> {
319.         // Reserve a slot index via compare-and-swap to avoid overshooting the counter.
320.         let idx: usize = loop {
321.             let current: usize = self.next_slot.load(Ordering::Acquire);
322.             if current >= S::NUM_UNITS {
323.                 return Err(BumpAllocError::Exhausted);
324.             }
325.             let next: usize = current.checked_add(1).ok_or(BumpAllocError::Overflow)?;
326.             if self
327.                 .next_slot
328.                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
329.                 .is_ok()
330.             {
331.                 break current;
332.             }
333.         };
334. 
335.         let stride: usize = align_up(N, A).ok_or(BumpAllocError::Overflow)?;
336.         let offset: usize = idx.checked_mul(stride).ok_or(BumpAllocError::Overflow)?;
337. 
338.         let base: usize = S::as_mut_ptr() as usize;
339.         let ptr: usize = base.checked_add(offset).ok_or(BumpAllocError::Overflow)?;
340.         let end: usize = ptr.checked_add(N).ok_or(BumpAllocError::Overflow)?;
341.         let storage_end: usize = base
342.             .checked_add(S::STORAGE_SIZE)
343.             .ok_or(BumpAllocError::Overflow)?;
344.         if end > storage_end {
345.             return Err(BumpAllocError::OutOfBounds);
346.         }
347.         if !ptr.is_multiple_of(A) {
348.             return Err(BumpAllocError::Misaligned);
349.         }
350. 
351.         // SAFETY: the backend contract guarantees valid stable storage; each slot index is handed
352.         // out at most once by atomic compare-and-swap.
353.         Ok(unsafe { &mut *(ptr as *mut [u8; N]) })
354.     }
355. 
356.     ///
357.     /// # Description
358.     ///
359.     /// Allocates the next fixed-size slot and reinterprets it as `MaybeUninit<T>`.
360.     ///
361.     /// # Returns
362.     ///
363.     /// On success, returns a mutable reference to an uninitialized `T`.
364.     ///
365.     /// # Errors
366.     ///
367.     /// - [`BumpAllocError::SizeMismatch`] if `size_of::<T>() != N`.
368.     /// - [`BumpAllocError::AlignmentMismatch`] if `align_of::<T>() > A`.
369.     /// - Any error from [`alloc()`](Self::alloc).
370.     ///
371.     /// # Safety
372.     ///
373.     /// The caller must initialise the returned `MaybeUninit<T>` before reading through it
374.     /// and ensure exclusive use of the returned reference.
375.     ///
376.     // SAFETY-SPEC: `external_body` for the same reason as `alloc` (it delegates to
377.     // `alloc` and then re-materializes the slot reference as `&'static mut
378.     // MaybeUninit<T>`). The size/alignment guard arms make the `T`-vs-`(N, A)`
379.     // contract caller-visible. Registered in `verus-ai-logs/tcb-allowed.md`.
380.     #[verus_verify(external_body)]
381.     #[verus_spec(result =>
382.         requires bump_view(self).inv(),
383.         ensures
384.             match result {
385.                 Ok(slot) => {
386.                     let v = bump_view(self);
387.                     let a = slot_ref_addr(slot);
388.                     &&& vstd::layout::size_of::<T>() == N as nat
389.                     &&& vstd::layout::align_of::<T>() <= A as nat
390.                     &&& a % (v.unit_align as int) == 0
391.                     &&& v.base <= a
392.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
393.                 },
394.                 Err(e) => {
395.                     &&& e == BumpAllocError::SizeMismatch
396.                         || e == BumpAllocError::AlignmentMismatch
397.                         || e == BumpAllocError::Exhausted
398.                     &&& (e == BumpAllocError::SizeMismatch ==> vstd::layout::size_of::<T>()
399.                         != N as nat)
400.                     &&& (e == BumpAllocError::AlignmentMismatch ==> vstd::layout::align_of::<T>()
401.                         > A as nat)
402.                 },
403.             },
404.     )]
405.     pub unsafe fn alloc_as<T>(&self) -> Result<&'static mut MaybeUninit<T>, BumpAllocError> {
406.         if core::mem::size_of::<T>() != N {
407.             return Err(BumpAllocError::SizeMismatch);
408.         }
409.         if core::mem::align_of::<T>() > A {
410.             return Err(BumpAllocError::AlignmentMismatch);
411.         }
412. 
413.         let slot: &'static mut [u8; N] = self.alloc()?;
414.         // SAFETY: size/alignment checks above guarantee this cast is valid.
415.         Ok(unsafe { &mut *(slot.as_mut_ptr() as *mut MaybeUninit<T>) })
416.     }
417. }
