 // Imports
 //==================================================================================================

 use ::core::{
     fmt,
     marker::PhantomData,
     mem::MaybeUninit,
     sync::atomic::{
         AtomicUsize,
         Ordering,
     },
 };
 use ::vstd::prelude::*;

 // Include specifications.
 #[cfg(verus_keep_ghost)]
