 ///
 /// # Description
 ///
 /// Aligns `value` up to the next multiple of `alignment`.
 ///
 /// # Parameters
 ///
 /// - `value`: Value to align.
 /// - `alignment`: Alignment boundary.
 ///
 /// # Returns
 ///
 /// Returns the aligned value, or `None` if `alignment` is zero or the computation overflows.
 ///
 #[verus_spec(result =>
     ensures
         match result {
             Some(r) => align_up_spec(value as nat, alignment as nat) == Some(r as nat),
             None => align_up_spec(value as nat, alignment as nat) is None,
         },
 )]
 pub const fn align_up(value: usize, alignment: usize) -> Option<usize> {
     if alignment == 0 {
         return None;
     }
     // VERUS REWRITE: the original body was
     //   `value.div_ceil(alignment).checked_mul(alignment)`.
     // Verus ships no specification for the `usize::div_ceil` intrinsic (confirmed:
     // not present in vstd `std_specs`; Verus emits "`core::num::<impl usize>::
     // div_ceil` is not supported"). The only ways to give it meaning are
     // `assume_specification`/`external_body`, both of which are unapproved cheating
     // for this function. Minimal reproducer with the captured Verus error:
     //   verus-ai-logs/nanvix-phys-bump-allocator/cheating-elimination/repro/div_ceil_no_spec.rs
     // The ceiling division is therefore open-coded into the arithmetically-
     // equivalent `value / alignment` (+1 on a non-zero remainder). This preserves
     // semantics and O(1) time/space. `qd + 1` cannot overflow because a non-zero
     // remainder forces `alignment >= 2`, hence `qd <= value / 2 < usize::MAX`
     // (see `lemma_ceil_div`).
     let r: usize = value % alignment;
     let qd: usize = value / alignment;
     proof! {
         vstd::arithmetic::div_mod::lemma_fundamental_div_mod(value as int, alignment as int);
         if r != 0 {
             assert(alignment >= 2);
             assert((alignment as int) * (qd as int) <= value as int);
             assert(2 * (qd as int) <= (alignment as int) * (qd as int)) by (nonlinear_arith)
                 requires
                     alignment >= 2,
                     qd >= 0,
             ;
             assert(qd < usize::MAX);
         }
     }
     let q: usize = if r == 0 { qd } else { qd + 1 };
     proof! {
         lemma_ceil_div(value as int, alignment as int, qd as int, r as int);
     }
     q.checked_mul(alignment)
 }

 ///
 /// # Description
 ///
 /// Error type returned by [`FixedSizeBumpAllocator`] operations.
 ///
 #[derive(Debug, Clone, Copy, PartialEq, Eq)]
 #[verus_verify]
 pub enum BumpAllocError {
     /// Storage capacity exhausted.
     Exhausted,
     /// Type size does not match allocator unit size.
     SizeMismatch,
     /// Type alignment exceeds allocator alignment.
     AlignmentMismatch,
     /// Internal arithmetic overflow.
     Overflow,
     /// Computed slot exceeds storage bounds.
     OutOfBounds,
     /// Computed slot is not properly aligned.
     Misaligned,
 }

