172. ///
173. /// # Description
174. ///
175. /// Error type returned by [`FixedSizeBumpAllocator`] operations.
176. ///
177. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
178. #[verus_verify]
179. pub enum BumpAllocError {
180.     /// Storage capacity exhausted.
181.     Exhausted,
182.     /// Type size does not match allocator unit size.
183.     SizeMismatch,
184.     /// Type alignment exceeds allocator alignment.
185.     AlignmentMismatch,
186.     /// Internal arithmetic overflow.
187.     Overflow,
188.     /// Computed slot exceeds storage bounds.
189.     OutOfBounds,
190.     /// Computed slot is not properly aligned.
