194. impl fmt::Display for BumpAllocError {
195.     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
196.         match self {
197.             Self::Exhausted => write!(f, "fixed-size BSS allocator exhausted"),
198.             Self::SizeMismatch => write!(f, "type size does not match allocator unit size"),
199.             Self::AlignmentMismatch => write!(f, "type alignment exceeds allocator alignment"),
200.             Self::Overflow => write!(f, "allocator internal arithmetic overflow"),
201.             Self::OutOfBounds => write!(f, "allocator slot exceeds storage bounds"),
202.             Self::Misaligned => write!(f, "allocator returned misaligned slot"),
203.         }
204.     }
