     unsafe impl BssStorage for BackendB {
         const NUM_UNITS: usize = 1;
         const STORAGE_SIZE: usize = 8;

         fn as_mut_ptr() -> *mut u8 {
             unsafe { core::ptr::addr_of_mut!(STORAGE_B.bytes) as *mut u8 }
         }
     }

