         unsafe { FixedSizeBumpAllocator::new() };

     #[test]
     fn alloc_as_allows_typed_access() {
         let slot: &mut core::mem::MaybeUninit<[u32; 2]> =
             unsafe { ALLOC_B.alloc_as::<[u32; 2]>().expect("alloc_as failed") };
