     requires
         v.inv(),
         v.has_capacity(),
     ensures
         v.spec_alloc().inv(),
         v.spec_alloc().allocated == v.allocated + 1,
         !v.is_consumed(v.allocated as int),
         v.spec_alloc().is_consumed(v.allocated as int),
